def find_tabs(self, custom_table_classes=None):
        """Finds all classes that are subcalss of Table and loads them into
         a dictionary named tables."""
        for module_name in get_all_modules(self.package_path):
            for name, _type in get_all_classes(module_name):
                # pylint: disable=W0640
                subclasses = [Table] + (custom_table_classes or list())
                iss_subclass = map(lambda c: issubclass(_type, c), subclasses)
                if isclass(_type) and any(iss_subclass):
                    self.tabs.update([[name, _type]])

def _check_filter_specific_md(self, specific_md: list):
        """Check if specific_md parameter is valid.

        :param list specific_md: list of specific metadata UUID to check
        """
        if isinstance(specific_md, list):
            if len(specific_md) > 0:
                # checking UUIDs and poping bad ones
                for md in specific_md:
                    if not self.check_is_uuid(md):
                        specific_md.remove(md)
                        logging.error("Metadata UUID is not correct: {}".format(md))
                # joining survivors
                specific_md = ",".join(specific_md)
            else:
                specific_md = ""
        else:
            raise TypeError("'specific_md' expects a list")
        return specific_md

