def get_comments_content_object(parser, token):
    """
    Get a limited set of comments for a given object.
    Defaults to a limit of 5. Setting the limit to -1 disables limiting.

    usage:

        {% get_comments_content_object for form_object as variable_name %}

    """
    keywords = token.contents.split()
    if len(keywords) != 5:
        raise template.TemplateSyntaxError(
            "'%s' tag takes exactly 2 arguments" % (keywords[0],))
    if keywords[1] != 'for':
        raise template.TemplateSyntaxError(
            "first argument to '%s' tag must be 'for'" % (keywords[0],))
    if keywords[3] != 'as':
        raise template.TemplateSyntaxError(
            "first argument to '%s' tag must be 'as'" % (keywords[0],))
    return GetCommentsContentObject(keywords[2], keywords[4])

def wrap_function(func):
    """
    RETURN A THREE-PARAMETER WINDOW FUNCTION TO MATCH
    """
    if is_text(func):
        return compile_expression(func)

    numarg = func.__code__.co_argcount
    if numarg == 0:

        def temp(row, rownum, rows):
            return func()

        return temp
    elif numarg == 1:

        def temp(row, rownum, rows):
            return func(row)

        return temp
    elif numarg == 2:

        def temp(row, rownum, rows):
            return func(row, rownum)

        return temp
    elif numarg == 3:
        return func

def last_versions_with_age(self, col_name='age'):
        '''
        Leaves only the latest version for each object.
        Adds a new column which represents age.
        The age is computed by subtracting _start of the oldest version
        from one of these possibilities::

            # psuedo-code
            if self._rbound is None:
                if latest_version._end is pd.NaT:
                    current_time is used
                else:
                    min(current_time, latest_version._end) is used
            else:
                if latest_version._end is pd.NaT:
                    self._rbound is used
                else:
                    min(self._rbound, latest_version._end) is used

        :param index: name of the new column.
        '''
        min_start_map = {}
        max_start_map = {}
        max_start_ser_map = {}

        cols = self.columns.tolist()
        i_oid = cols.index('_oid')
        i_start = cols.index('_start')
        i_end = cols.index('_end')
        for row in self.values:
            s = row[i_start]
            oid = row[i_oid]
            mins = min_start_map.get(oid, s)
            if s <= mins:
                min_start_map[oid] = s
            maxs = max_start_map.get(oid, s)
            if s >= maxs:
                max_start_map[oid] = s
                max_start_ser_map[oid] = row

        vals = max_start_ser_map.values()
        cut_ts = datetime.utcnow()
        ages = []
        for row in vals:
            end = row[i_end]
            end = cut_ts if end is pd.NaT else min(cut_ts, end)
            age = end - min_start_map[row[i_oid]]
            age = age - timedelta(microseconds=age.microseconds)
            ages.append(age)

        res = pd.DataFrame(max_start_ser_map.values(), columns=cols)
        res[col_name] = pd.Series(ages, index=res.index)
        return res

def current_position(self):
        """Return a tuple of (start, end)."""
        token = self.tokenizer.peek(0)
        if token:
            return token.start, token.end

        return self.tokenizer.position, self.tokenizer.position + 1

def selector_to_text(sel, guess_punct_space=True, guess_layout=True):
    """ Convert a cleaned parsel.Selector to text.
    See html_text.extract_text docstring for description of the approach
    and options.
    """
    import parsel
    if isinstance(sel, parsel.SelectorList):
        # if selecting a specific xpath
        text = []
        for s in sel:
            extracted = etree_to_text(
                s.root,
                guess_punct_space=guess_punct_space,
                guess_layout=guess_layout)
            if extracted:
                text.append(extracted)
        return ' '.join(text)
    else:
        return etree_to_text(
            sel.root,
            guess_punct_space=guess_punct_space,
            guess_layout=guess_layout)

def rowsAfterValue(self, value, count):
        """
        Retrieve some rows at or after a given sort-column value.

        @param value: Starting value in the index for the current sort column
        at which to start returning results.  Rows with a column value for the
        current sort column which is greater than or equal to this value will
        be returned.

        @type value: Some type compatible with the current sort column, or
        None, to specify the beginning of the data.

        @param count: The maximum number of rows to return.
        @type count: C{int}

        @return: A list of row data, ordered by the current sort column,
        beginning at C{value} and containing at most C{count} elements.
        """
        if value is None:
            query = self.inequalityQuery(None, count, True)
        else:
            pyvalue = self._toComparableValue(value)
            currentSortAttribute = self.currentSortColumn.sortAttribute()
            query = self.inequalityQuery(currentSortAttribute >= pyvalue, count, True)
        return self.constructRows(query)

def payload_generator(levels=0, dimensions=None, sequential=True, string=True, max_int=255, max_pkt_len=150, max_dim_size=3):
    """ Generates random data in a form of nested lists, to be used as a test packet payload
            levels - nesting levels:
                0 - list of integers (single packet payload)
                1 - list of lists of integers (list of packets)
                2 - list of lists of lists of integers (list of packets, each packet containing list of messages)
                etc.
            dimensions - specifies the size of the lists; the specification can be partial, as what is not specified will be chosen randomly
                if level=0:
                    dimensions=None - list of integers of random length in the range [1,max_pkt_len]
                    dimensions=5 - list of integers of length 5
                if level=1:
                    dimensions=None - list of random length in the range [1, max_dim_size], each element is an integer list of random length in the range [1, max_pkt_len]
                    dimensions=5 - list of length 5, each element is an integer list of random length in the range [1, max_pkt_len]
                    dimensions=[2, 3] - list of 2 elements, each element is an integer list, the first one of length 2, the second on of length 3
                if level=2:
                    dimensions=None - list of random length in the range [1, max_dim_size], each element is a list of random length in the range [1, max_dim_size], 
                                      each element of the second level lists is an integer list of random length in the range [1, max_pkt_len]
                    dimensions=5 - list of length 5, each element is a list of random length in the range [1, max_dim_size], each element of the second level lists 
                                   is an integer list of random length in the range [1, max_pkt_len]
                    dimensions=[2, 3] - list of 2 elements, each element is a list, the first one of length 2, the second on of length 3, each element of the second 
                                        level lists is an integer list of random length in the range [1, max_pkt_len]
                    dimensions=[[3, 5], [6, 7, 8]] - list of 2 elements, each element is a list, the first one of length 2, the second on of length 3, each element of the second 
                                        level lists is an integer list of length respectively 3, 5, 6, 7, 8
                if level=3:
                    etc.
                It is possible to specify dimensions partially, e.g dimensions=[[3, None], [6, 7, 8]] or dimensions=[None, [6, 7, 8]]. Dimensions that are not specified are 
                chosen randomly
            sequential - if True, the payload is a cyclic sequence if integers in the range [0, max_int]
                         if False, the payload is a sequence of random integers in the range [0, max_int]
            string - if True, the payload is a byte string, e.g. '\x04\x05\x06\x07' as each byte is in the range [0, min(255, max_int)]
                     if False, the payload is a list of integers in the range [0, max_int]
            max_int - Upper limit for the integer range for the payload
            max_pkt_len - Upper limit for the randomly chosen payload length
            max_dim_size - Upper limit for the randomly chosen dimension sizes
    """

    MAX_INT = max_int
    if string:
        MAX_INT = min(255, max_int)

    MAX_DIM_SIZE = max_dim_size
    MAX_PKT_LEN = max_pkt_len

    def next_i():
        ''' Generates next number from a cyclic integer sequence [0..MAX_INT]'''
        next_i.i = (next_i.i+1)%(MAX_INT+1)
        return next_i.i
    next_i.i = 0;

    def payload(length):
        ''' Generates payload of given length '''
        if (sequential) :
            pld = [next_i() for _ in xrange(length)]
        else:
            pld = [random.randint(0, MAX_INT) for _ in xrange(length)]
        if string:
            pld = str(bytearray(pld))
        return pld

    def next_level(level, pld):
        ''' Generates the next level of nested lists '''
        if level>0:
            # Next level of nested lists
            if pld==None:
                pld = random.randint(1, MAX_DIM_SIZE)
            if isinstance(pld, int):
                pld = pld*[None]
            if isinstance(pld, list):
                for i in range(len(pld)):
                    pld[i] = next_level(level-1, pld[i])
                return pld
            else:
                raise TypeError("Expected None, int or list, got {}: {}".format(type(pld), pld))
        elif level==0:
            # Generate payload
            if pld==None:
                pld = random.randint(1, MAX_PKT_LEN)
            if isinstance(pld, int):
                return payload(pld)
            else:
                raise TypeError("Expected None or int, got {}: {}".format(type(pld), pld))
        else:
            raise ValueError("Expected int>=0, got {}".format(level))

    pld = copy.deepcopy(dimensions)

    pld = next_level(levels, pld)

    return pld

def p_additional_catches(p):
    '''additional_catches : additional_catches CATCH LPAREN fully_qualified_class_name VARIABLE RPAREN LBRACE inner_statement_list RBRACE
                          | empty'''
    if len(p) == 10:
        p[0] = p[1] + [ast.Catch(p[4], ast.Variable(p[5], lineno=p.lineno(5)),
                                 p[8], lineno=p.lineno(2))]
    else:
        p[0] = []

def remove(self, value):
        """Remove the first occurence of *value*."""
        def remove_trans(pipe):
            # If we're caching, we'll need to synchronize before removing.
            if self.writeback:
                self._sync_helper(pipe)

            delete_count = pipe.lrem(self.key, 1, self._pickle(value))
            if delete_count == 0:
                raise ValueError

        self._transaction(remove_trans)

def avatar_url_from_email(email, size=64, default='retro', dns=False):
    """
    Our own implementation since fas doesn't support this nicely yet.
    """

    if dns:
        # This makes an extra DNS SRV query, which can slow down our webapps.
        # It is necessary for libravatar federation, though.
        import libravatar
        return libravatar.libravatar_url(
            email=email,
            size=size,
            default=default,
        )
    else:
        params = _ordered_query_params([('s', size), ('d', default)])
        query = parse.urlencode(params)
        hash = md5(email.encode('utf-8')).hexdigest()
        return "https://seccdn.libravatar.org/avatar/%s?%s" % (hash, query)

def duration(self):
        """Calculates the breeding cage's duration.

        This is relative to the current date (if alive) or the date of inactivation (if not).
        The duration is formatted in days."""
        if self.End:
            age =  self.End - self.Start
        else:    
            age =  datetime.date.today() - self.Start
        return age.days

def _schema_getter(self, db):
        """Retrieve a dictionary representing a database's data schema."""
        # Change DB connection if needed
        if self.database != db:
            self.change_db(db)
        schema_dict = {tbl: self.get_schema(tbl) for tbl in self.tables}

        schema_lst = []
        for table, schema in schema_dict.items():
            for col in schema:
                col.insert(0, table)
                schema_lst.append(col)
        return schema_lst

def render(self, context):
        """
        Render the tag, with extra context layer.
        """
        extra_context = self.context_expr.resolve(context)
        if not isinstance(extra_context, dict):
            raise TemplateSyntaxError("{% withdict %} expects the argument to be a dictionary.")

        with context.push(**extra_context):
            return self.nodelist.render(context)

def find_resource_url_basename(self, resource_url):
        '''
        Figure out path basename for given resource_url
        '''
        scheme = resource_url.parsed.scheme
        if scheme in ('http', 'https', 'file'):
            return _get_basename_based_on_url(resource_url)

        elif scheme in ('git', 'git+https', 'git+http'):
            if len(resource_url.args) == 2:
                # For now, git has 2 positional args, hash and path
                git_tree, subpath = resource_url.args
                basename = os.path.basename(subpath)
                if basename:
                    return basename  # subpath was not '/' or ''
        return _get_basename_based_on_url(resource_url)

