def getStartTag(self):
        '''
            getStartTag - Returns the start tag represented as HTML

            @return - String of start tag with attributes
        '''
        attributeStrings = []
        # Get all attributes as a tuple (name<str>, value<str>)
        for name, val in self._attributes.items():
            # Get all attributes
            if val:
                val = tostr(val)

            # Only binary attributes have a "present/not present"
            if val or name not in TAG_ITEM_BINARY_ATTRIBUTES:
                # Escape any quotes found in the value
                val = escapeQuotes(val)

                # Add a name="value" to the resulting string
                attributeStrings.append('%s="%s"' %(name, val) )
            else:
                # This is a binary attribute, and thus only includes the name ( e.x. checked )
                attributeStrings.append(name)

        # Join together all the attributes in @attributeStrings list into a string
        if attributeStrings:
            attributeString = ' ' + ' '.join(attributeStrings)
        else:
            attributeString = ''

        # If this is a self-closing tag, generate like  <tag attr1="val" attr2="val2" />  with the close "/>"
        # Include the indent prior to tag opening
        if self.isSelfClosing is False:
            return "%s<%s%s >" %(self._indent, self.tagName, attributeString)
        else:
            return "%s<%s%s />" %(self._indent, self.tagName, attributeString)

def _read_config(filename):
    """Read configuration from the given file.

    Parsing is performed through the configparser library.

    Returns:
        dict: a flattened dict of (option_name, value), using defaults.
    """
    parser = configparser.RawConfigParser()
    if filename and not parser.read(filename):
        sys.stderr.write("Unable to open configuration file %s. Use --config='' to disable this warning.\n" % filename)

    config = {}

    for section, defaults in BASE_CONFIG.items():
        # Patterns are handled separately
        if section == 'patterns':
            continue

        for name, descr in defaults.items():
            kind, default = descr
            if section in parser.sections() and name in parser.options(section):
                if kind == 'int':
                    value = parser.getint(section, name)
                elif kind == 'float':
                    value = parser.getfloat(section, name)
                elif kind == 'bool':
                    value = parser.getboolean(section, name)
                else:
                    value = parser.get(section, name)
            else:
                value = default
            config[name] = value

    if 'patterns' in parser.sections():
        patterns = [parser.get('patterns', opt) for opt in parser.options('patterns')]
    else:
        patterns = DEFAULT_PATTERNS
    config['patterns'] = patterns

    return config

def subtree(self, event, create = False):
        '''
        Find a subtree from an event
        '''
        current = self
        for i in range(self.depth, len(event.indices)):
            if not hasattr(current, 'index'):
                return current
            ind = event.indices[i]
            if create:
                current = current.index.setdefault(ind, EventTree(current, self.branch))
                current.parentIndex = ind
            else:
                current = current.index.get(ind)
                if current is None:
                    return None
        return current

