def blob_handler(self, cmd):
        """Process a BlobCommand."""
        self.cmd_counts[cmd.name] += 1
        if cmd.mark is None:
            self.blobs['unmarked'].add(cmd.id)
        else:
            self.blobs['new'].add(cmd.id)
            # Marks can be re-used so remove it from used if already there.
            # Note: we definitely do NOT want to remove it from multi if
            # it's already in that set.
            try:
                self.blobs['used'].remove(cmd.id)
            except KeyError:
                pass

def calc_lfp_layer(self):
        """
        Calculate the LFP from concatenated subpopulations residing in a
        certain layer, e.g all L4E pops are summed, according to the `mapping_Yy`
        attribute of the `hybridLFPy.Population` objects.
        """
        LFPdict = {}

        lastY = None
        for Y, y in self.mapping_Yy:
            if lastY != Y:
                try:
                    LFPdict.update({Y : self.LFPdict[y]})
                except KeyError:
                    pass
            else:
                try:
                    LFPdict[Y] += self.LFPdict[y]
                except KeyError:
                    pass
            lastY = Y

        return LFPdict

