def match_indices(match):
    """Yield index tuples (old_index, new_index) for each place in the match."""
    a, b, size = match
    for i in range(size):
        yield a + i, b + i

def setslice_with_length(self, startindex, endindex, fs, length):
        """Shim for easily converting old __setitem__ calls"""
        if len(self) < startindex:
            fs = ' '*(startindex - len(self)) + fs
        if len(self) > endindex:
            fs = fs + ' '*(endindex - startindex - len(fs))
            assert len(fs) == endindex - startindex, (len(fs), startindex, endindex)
        result = self.splice(fs, startindex, endindex)
        assert len(result) <= length
        return result

def unpacked_contents(self):
        """
        :return:
        """

        from nbformat import read

        import msgpack

        if self.mime_type == 'text/plain':
            return self.contents.decode('utf-8')
        elif self.mime_type == 'application/msgpack':
            # FIXME: Note: I'm not sure that encoding='utf-8' will not break old data.
            # We need utf-8 to make python3 to work. (kazbek)
            # return msgpack.unpackb(self.contents)
            return msgpack.unpackb(self.contents, encoding='utf-8')
        else:
            return self.contents

